import re, csv
data=open(GRAPH_TTL).read()
triples=[]
subj=None
for raw in data.splitlines():
    ln=raw.strip().rstrip('.')
    if not ln or ln.startswith('@'): continue
    first=ln.split()[0]
    # new subject detection: starts with bldg: or <urn
    if re.match(r'^(?:<[^>]+>|bldg:[A-Za-z0-9_.-]+)$', first) or (re.match(r'^(?:bldg:[A-Za-z0-9_.-]+|<[^\s>]+>) (a|brick:|ref:)', ln)):
        subj=first
    for pm in re.finditer(r'\b(a|brick:isPointOf|ref:hasExternalReference|ref:hasTimeseriesId) ("[^"]+"|<[^>]+>|\S+)', ln):
        p=pm.group(1); o=pm.group(2).strip('<>"')
        if subj: triples.append((subj,p,o))

uts={}
for s,p,o in triples:
    if p=='ref:hasTimeseriesId': uts[s]=o

# point-level
ptyp={};pzone={};pref={}
for s,p,o in triples:
    if s.startswith('bldg:') :
        if p=='a' and 'brick:' in o: ptyp[s]=o
        if p=='brick:isPointOf': pzone[s]=o
        if p=='ref:hasExternalReference': pref[s]=o

TEMP='brick:Zone_Air_Temperature_Sensor'; COOL='brick:Zone_Air_Cooling_Temperature_Setpoint'
zones={}
for pt,typ in ptyp.items():
    z=pzone.get(pt); urn=pref.get(pt); tsid=uts.get(urn)
    if not(z and tsid): continue
    zones.setdefault(z,{})
    if typ==TEMP: zones[z]['t']=tsid
    if typ==COOL: zones[z]['c']=tsid
both={z:v for z,v in zones.items() if 't' in v and 'c' in v}
print("both count:", len(both))
mapping={z:v for z,v in both.items()}
import json
open('/tmp/zmap.json','w').write(json.dumps(mapping))
for z,v in sorted(mapping.items()): print(z, v)
